test('public no-pool adapter forwards one request and all request semantics with response identity unread',async()=>{const body=new Uint8Array([1,2]),headers=new Headers({authorization:'Bearer fictional'}),signal=AbortSignal.timeout(30_000),request=new Request('https://www.neuvetra.ai/ready',{method:'POST'}),response=new Response('untouched');let calls=0,seenRaw:any,seenInit:any;const original:any={method:'PUT',body,headers,signal,redirect:'manual',keepalive:true};const wrapped=m78Continuation4NoPoolFetch((async(raw:RequestInfo|URL,init?:RequestInit)=>{calls++;seenRaw=raw;seenInit=init;return response})as any);expect(await wrapped(request,original)).toBe(response);expect(calls).toBe(1);expect(seenRaw).toBe(request);expect(seenInit).toMatchObject({method:'PUT',body,headers,signal,redirect:'manual',keepalive:false});expect(original.keepalive).toBe(true);expect(response.bodyUsed).toBe(false)});
